WITH enriched AS (SELECT *, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY status), 4) AS monthly_fee_share, LEAD(monthly_fee, 2) OVER (PARTITION BY customer_id ORDER BY end_date, id) AS next_monthly_fee, ROW_NUMBER() OVER (PARTITION BY status ORDER BY end_date, id) AS seq_no, ROW_NUMBER() OVER (PARTITION BY MONTH(end_date) ORDER BY end_date DESC, id) AS row_seq, MIN(monthly_fee) OVER (PARTITION BY customer_id) AS customer_id_min_monthly_fee FROM subscriptions) SELECT id, customer_id, plan, end_date, monthly_fee, monthly_fee_share, row_seq, customer_id_min_monthly_fee FROM enriched ORDER BY end_date DESC NULLS LAST, id;
